class Solution {
    bool check(int idx, unsigned long long prev, const string& s) {
        if (idx == s.size()) return true;
        unsigned long long val = 0;
        for (int j = idx; j < s.size(); ++j) {
            val = val * 10 + (s[j] - '0');
            if (val == prev - 1 && check(j + 1, val, s)) return true;
            if (val >= prev) break;
        }
        return false;
    }
