class Solution {
    private boolean check(int idx, long prev, String s) {
        if (idx == s.length()) return true;
        long val = 0;
        for (int j = idx; j < s.length(); ++j) {
            val = val * 10 + (s.charAt(j) - '0');
            if (val == prev - 1 && check(j + 1, val, s)) return true;
            if (val >= prev) break;
        }
        return false;
    }

    public boolean splitString(String s) {
        long firstVal = 0;
        for (int i = 0; i < s.length() - 1; ++i) {
            firstVal = firstVal * 10 + (s.charAt(i) - '0');
            if (firstVal > 1e16) break;
            if (check(i + 1, firstVal, s)) return true;
        }
        return false;
    }
}

